import React, { useEffect, useState, useCallback } from "react";
import { v4 as uuidv4 } from 'uuid';
import { Question, Message, DomainStatus } from './types';
import Header from './components/Header';
import ChatPanel from './components/ChatPanel';
import Sidebar from './components/Sidebar';

const App: React.FC = () => {
  const [questions, setQuestions] = useState<Question[]>([]);
  const [currentQuestionId, setCurrentQuestionId] = useState<number | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [domainStatuses, setDomainStatuses] = useState<DomainStatus[]>([]);
  const [overallScore, setOverallScore] = useState<number>(0);
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [editingMessageId, setEditingMessageId] = useState<string | null>(null);

  useEffect(() => {
    fetch("http://localhost:3001/questions").then(res => {
        if (!res.ok) throw new Error(`Network response was not ok: ${res.statusText}`);
        return res.json();
    }).then(data => {
      if (!Array.isArray(data) || data.length === 0) throw new Error("Fetched data is not valid.");
      setQuestions(data);
      const firstQuestion = data[0];
      setCurrentQuestionId(firstQuestion.id);
      setMessages([{ id: uuidv4(), sender: 'AI', text: "Welcome!", type: 'question', question: firstQuestion }]);
      const initialDomains: DomainStatus[] = [...new Set(data.map(q => q.domain_name))].map(name => ({ name, status: name === firstQuestion.domain_name ? 'In Progress' : 'Pending', score: 0 }));
      setDomainStatuses(initialDomains);
    }).catch(err => {
      console.error("Error fetching questions:", err);
      setMessages([{ id: uuidv4(), sender: 'AI', text: "Backend'e bağlanılamadı.", type: 'error', question: undefined }]);
    }).finally(() => setIsLoading(false));
  }, []);

  const recalculateScores = useCallback((updatedMessages: Message[], allQuestions: Question[]) => {
    if (allQuestions.length === 0) return;

    // 1. Initialize a data structure to hold score and progress for each domain.
    const domainData: { [key: string]: { score: number; answeredCount: number; totalQuestions: number } } = {};
    const domains = [...new Set(allQuestions.map(q => q.domain_name))];

    domains.forEach(name => {
      domainData[name] = {
        score: 0,
        answeredCount: 0,
        totalQuestions: allQuestions.filter(q => q.domain_name === name).length,
      };
    });

    // 2. Iterate through the entire message history to calculate the current score for each domain.
    for (let i = 0; i < updatedMessages.length; i++) {
      const msg = updatedMessages[i];
      if (msg.type === 'user_response' && msg.answeredQuestionId) {
        const question = allQuestions.find(q => q.id === msg.answeredQuestionId);
        const feedback = updatedMessages[i + 1]; // The subsequent message is the feedback.

        if (question && feedback && feedback.type === 'feedback' && typeof feedback.score === 'number') {
          const domainName = question.domain_name;
          const questionWeight = 100 / (domainData[domainName].totalQuestions || 1);
          
          domainData[domainName].score += (feedback.score / 100) * questionWeight;
          domainData[domainName].answeredCount += 1;
        }
      }
    }

    // 3. Determine the status ('Complete', 'In Progress', 'Pending') of each domain.
    const lastQuestionMsg = updatedMessages.slice().reverse().find(m => m.type === 'question' && m.question);
    const currentDomainName = lastQuestionMsg?.question?.domain_name;

    const newDomainStatuses: DomainStatus[] = domains.map(name => {
      const data = domainData[name];
      let status: 'Complete' | 'In Progress' | 'Pending' = 'Pending';

      if (data.answeredCount > 0) {
        if (data.answeredCount >= data.totalQuestions) {
          status = 'Complete';
        } else if (name === currentDomainName) {
          status = 'In Progress';
        } else {
          // If we've started a domain but moved on before finishing, consider it 'Complete' for progress tracking.
          status = 'Complete';
        }
      } else if (name === currentDomainName) {
        status = 'In Progress';
      }
      
      return { name, score: Math.min(100, data.score), status };
    });

    // 4. Update the React states to refresh the UI.
    const totalScore = newDomainStatuses.reduce((acc, curr) => acc + curr.score, 0);
    setOverallScore(totalScore / (newDomainStatuses.length || 1));
    setDomainStatuses(newDomainStatuses);
    console.log("Scores have been recalculated and updated.");

  }, []);


  const handleSendMessage = async (prompt: string) => {
    if (!currentQuestionId || isLoading) return;
    setIsLoading(true);

    const userMessage: Message = { 
      id: uuidv4(), 
      sender: 'User', 
      text: prompt, 
      type: 'user_response',
      answeredQuestionId: currentQuestionId 
    };
    
    // Temporarily update messages to show user's prompt immediately
    const tempMessages = [...messages, userMessage];
    setMessages(tempMessages);

    try {
      const res = await fetch("http://localhost:3001/ask", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ prompt, previous_question_id: currentQuestionId }) });
      if (!res.ok) throw new Error(`API error: ${res.statusText}`);
      const apiResponse = await res.json();
      
      const feedbackMessage: Message = {
          id: uuidv4(),
          sender: 'AI',
          text: 'Feedback for your answer.',
          type: 'feedback',
          ai_comment: apiResponse.comment,
          ai_task: apiResponse.task,
          db_answer_id: apiResponse.db_answer_id,
          score: apiResponse.score, // Storing the score on the feedback message
      };
      
      const newMessages: Message[] = [feedbackMessage];
      const nextQuestion = questions.find(q => q.id === apiResponse.next_question_id);
      
      if (nextQuestion) {
        newMessages.push({ id: uuidv4(), sender: 'AI', text: 'Here is the next question.', type: 'question', question: nextQuestion });
        setCurrentQuestionId(apiResponse.next_question_id);
      } else {
        newMessages.push({ id: uuidv4(), sender: 'AI', text: '🎉 Assessment complete!', type: 'question', question: undefined });
        setCurrentQuestionId(null);
      }
      
      const finalMessages = [...tempMessages, ...newMessages];
      setMessages(finalMessages);
      recalculateScores(finalMessages, questions); // Recalculate scores with the new messages

    } catch (err) {
      console.error("Error sending message:", err);
      // Revert to original messages if API call fails
      setMessages(messages); 
      // Add an error message
      setMessages(prev => [...prev, { id: uuidv4(), sender: 'AI', text: "An error occurred while sending the message.", type: 'error', question: undefined }]);
    } finally {
      setIsLoading(false);
    }
  };

  const handleEditMessage = async (messageId: string, newText: string) => {
    const messageIndex = messages.findIndex(m => m.id === messageId);
    if (messageIndex === -1) return;

    const originalMessage = messages[messageIndex];
    const feedbackMessage = messages[messageIndex + 1];
    const dbAnswerId = feedbackMessage?.db_answer_id;
    const questionId = originalMessage.answeredQuestionId;

    if (!dbAnswerId || !questionId) {
        console.error("Could not find the database ID for the message to be edited.");
        return;
    }

    setIsLoading(true);
    setEditingMessageId(null);

    try {
        const res = await fetch("http://localhost:3001/ask", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ prompt: newText, previous_question_id: questionId, answer_id_to_edit: dbAnswerId }),
        });
        if (!res.ok) throw new Error(`API error: ${res.statusText}`);
        const apiResponse = await res.json();

        // 1. Create a new history up to the point of the edited message.
        const newHistory = messages.slice(0, messageIndex);
        
        // 2. Create the updated user message and its corresponding feedback.
        const updatedUserMessage: Message = { ...originalMessage, text: newText };
        const updatedFeedbackMessage: Message = { ...feedbackMessage, ai_comment: apiResponse.comment, ai_task: apiResponse.task, score: apiResponse.score };

        // 3. Find the next question based on the new branching logic.
        const newNextQuestion = questions.find(q => q.id === apiResponse.next_question_id);
        const newMessagesToAdd: Message[] = [updatedUserMessage, updatedFeedbackMessage];

        if (newNextQuestion) {
            newMessagesToAdd.push({ id: uuidv4(), sender: 'AI', text: 'Here is the next question.', type: 'question', question: newNextQuestion });
            setCurrentQuestionId(apiResponse.next_question_id);
        } else {
            newMessagesToAdd.push({ id: uuidv4(), sender: 'AI', text: '🎉 Assessment complete!', type: 'question', question: undefined });
            setCurrentQuestionId(null);
        }

        // 4. Set the final message history.
        const finalMessages = [...newHistory, ...newMessagesToAdd];
        setMessages(finalMessages);
        
        // 5. Recalculate all scores from scratch based on the new, updated history.
        recalculateScores(finalMessages, questions);

    } catch (err) {
        console.error("Error while editing message:", err);
    } finally {
        setIsLoading(false);
    }
  };

  const handlePreviousQuestion = () => {
    const lastUserResponseIndex = messages.findLastIndex(m => m.type === 'user_response');
    if (lastUserResponseIndex === -1) return; 

    const previousQuestionMessage = messages.slice(0, lastUserResponseIndex).findLast(m => m.type === 'question');
    if (!previousQuestionMessage || !previousQuestionMessage.question) return;
    
    // 1. Revert the message history to before the last user response.
    const newMessages = messages.slice(0, lastUserResponseIndex);
    setMessages(newMessages);
    setCurrentQuestionId(previousQuestionMessage.question.id);
    
    // 2. Recalculate scores based on the reverted history.
    recalculateScores(newMessages, questions);
  };

  return (
    <div className="bg-[#0f0f23] text-gray-200 font-sans h-screen flex flex-col">
      <Header onPrevious={handlePreviousQuestion} canGoBack={messages.some(m => m.type === 'user_response')} />
      <div className="flex flex-1 overflow-hidden min-h-0">
        <ChatPanel 
          messages={messages} 
          onSendMessage={handleSendMessage} 
          isLoading={isLoading} 
          currentQuestionId={currentQuestionId}
          editingMessageId={editingMessageId}
          setEditingMessageId={setEditingMessageId}
          onEditMessage={handleEditMessage}
        />
        <Sidebar statuses={domainStatuses} overallScore={overallScore} />
      </div>
    </div>
  );
};

export default App;
